// ---- helpers, requester domain ----
int unsigned mst_wcnt = 0;
int unsigned mst_idle = 0;
logic mst_prev_ready = 1'b0;
logic mst_is_wr = 1'b0;
logic mst_last_err = 1'b0;
logic mst_active = 1'b0;
logic mst_lost = 1'b0;
logic [PARA_APBCDC_ADDR_W-1:0] mst_cap_addr = '0;

always_ff @(posedge i_clk_mst) begin
  if (!i_rst_n_mst) begin
    mst_lost <= mst_lost | mst_active;
    mst_active <= 1'b0;
    mst_wcnt <= 0;
    mst_idle <= 0;
    mst_prev_ready <= 1'b0;
    mst_last_err <= 1'b0;
  end else begin
    mst_lost <= 1'b0;
    mst_prev_ready <= o_apb_pready;
    if (i_apb_psel) mst_idle <= 0;
    else if (mst_idle < 1000) mst_idle <= mst_idle + 1;
    if (o_apb_pready) begin
      mst_active <= 1'b0;
      mst_last_err <= o_apb_pslverr;
      mst_wcnt <= 0;
    end else if (i_apb_psel && !i_apb_penable) begin
      mst_active <= 1'b1;
      mst_is_wr <= i_apb_pwrite;
      mst_cap_addr <= i_apb_paddr;
      mst_wcnt <= 0;
    end else if (i_apb_psel && i_apb_penable && (mst_wcnt < 1000)) begin
      mst_wcnt <= mst_wcnt + 1;
    end
  end
end

// ---- helpers, completer domain ----
int unsigned slv_wcnt = 0;
logic slv_busy = 1'b0;
logic slv_lost = 1'b0;

always_ff @(posedge i_clk_slv) begin
  if (!i_rst_n_slv) begin
    slv_lost <= slv_lost | slv_busy;
    slv_busy <= 1'b0;
    slv_wcnt <= 0;
  end else begin
    slv_lost <= 1'b0;
    slv_busy <= o_apb_psel && !(o_apb_penable && i_apb_pready);
    if (o_apb_psel && o_apb_penable) begin
      if (i_apb_pready) slv_wcnt <= 0;
      else if (slv_wcnt < 1000) slv_wcnt <= slv_wcnt + 1;
    end else begin
      slv_wcnt <= 0;
    end
  end
end

// COVP-001: Requester write Setup cycle
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && i_apb_pwrite)) hits_COVP_001 <= hits_COVP_001 + 1;
// COVP-002: Requester read Setup cycle
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && !i_apb_pwrite)) hits_COVP_002 <= hits_COVP_002 + 1;
// COVP-003: Write completes without error
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && !o_apb_pslverr && mst_is_wr)) hits_COVP_003 <= hits_COVP_003 + 1;
// COVP-004: Write completes with error
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && o_apb_pslverr && mst_is_wr)) hits_COVP_004 <= hits_COVP_004 + 1;
// COVP-005: Read completes without error
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && !o_apb_pslverr && !mst_is_wr)) hits_COVP_005 <= hits_COVP_005 + 1;
// COVP-006: Read error with nonzero read data forwarded
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && o_apb_pslverr && !mst_is_wr && (|o_apb_prdata))) hits_COVP_006 <= hits_COVP_006 + 1;
// COVP-007: Completion after 8 or more requester wait cycles
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && mst_wcnt >= 8)) hits_COVP_007 <= hits_COVP_007 + 1;
// COVP-008: Completion after 32 or more requester wait cycles
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && mst_wcnt >= 32)) hits_COVP_008 <= hits_COVP_008 + 1;
// COVP-009: Completion after 128 or more requester wait cycles
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && mst_wcnt >= 128)) hits_COVP_009 <= hits_COVP_009 + 1;
// COVP-010: Back-to-back Setup right after PREADY cycle
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && mst_prev_ready)) hits_COVP_010 <= hits_COVP_010 + 1;
// COVP-011: Back-to-back write then read
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && mst_prev_ready && mst_is_wr && !i_apb_pwrite)) hits_COVP_011 <= hits_COVP_011 + 1;
// COVP-012: Back-to-back read then write
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && mst_prev_ready && !mst_is_wr && i_apb_pwrite)) hits_COVP_012 <= hits_COVP_012 + 1;
// COVP-013: Back-to-back write then write
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && mst_prev_ready && mst_is_wr && i_apb_pwrite)) hits_COVP_013 <= hits_COVP_013 + 1;
// COVP-014: Back-to-back read then read
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && mst_prev_ready && !mst_is_wr && !i_apb_pwrite)) hits_COVP_014 <= hits_COVP_014 + 1;
// COVP-015: Setup after idle period of 4 or more cycles
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && mst_idle >= 4)) hits_COVP_015 <= hits_COVP_015 + 1;
// COVP-016: Error-free transfer following an error transfer
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && !o_apb_pslverr && mst_last_err)) hits_COVP_016 <= hits_COVP_016 + 1;
// COVP-017: Consecutive error transfers
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && o_apb_pslverr && mst_last_err)) hits_COVP_017 <= hits_COVP_017 + 1;
// COVP-018: Address all ones in Setup
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && (&i_apb_paddr))) hits_COVP_018 <= hits_COVP_018 + 1;
// COVP-019: Write with full strobes at word-aligned address
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && i_apb_pwrite && (&i_apb_pstrb) && ((i_apb_paddr % 4) == 0))) hits_COVP_019 <= hits_COVP_019 + 1;
// COVP-020: Write with partial or zero strobes at misaligned address
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && i_apb_pwrite && !(&i_apb_pstrb) && ((i_apb_paddr % 4) != 0))) hits_COVP_020 <= hits_COVP_020 + 1;
// COVP-021: Read with nonzero PSTRB forwarded
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && !i_apb_pwrite && (|i_apb_pstrb))) hits_COVP_021 <= hits_COVP_021 + 1;
// COVP-022: PPROT equal 0 in Setup
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && i_apb_pprot == 3'b000)) hits_COVP_022 <= hits_COVP_022 + 1;
// COVP-023: PPROT equal 7 in Setup
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && i_apb_pprot == 3'b111)) hits_COVP_023 <= hits_COVP_023 + 1;
// COVP-024: PPROT with a single bit set in Setup
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && (i_apb_pprot == 3'b001 || i_apb_pprot == 3'b010 || i_apb_pprot == 3'b100))) hits_COVP_024 <= hits_COVP_024 + 1;
// COVP-025: Requester changes fields during Access
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (mst_active && i_apb_psel && i_apb_penable && !o_apb_pready && ((i_apb_paddr != mst_cap_addr) || (i_apb_pwrite != mst_is_wr)))) hits_COVP_025 <= hits_COVP_025 + 1;
// COVP-026: APB5 wake-up high at Setup
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && i_apb_pwakeup)) hits_COVP_026 <= hits_COVP_026 + 1;
// COVP-027: Requester wake-up low at Setup
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && !i_apb_pwakeup)) hits_COVP_027 <= hits_COVP_027 + 1;
// COVP-028: Request user attributes nonzero
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (i_apb_psel && !i_apb_penable && ((|i_apb_pauser) || (i_apb_pwrite && (|i_apb_pwuser))))) hits_COVP_028 <= hits_COVP_028 + 1;
// COVP-029: Response user attributes nonzero at completion
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (o_apb_pready && ((|o_apb_pbuser) || (!mst_is_wr && (|o_apb_pruser))))) hits_COVP_029 <= hits_COVP_029 + 1;
// COVP-030: Requester-domain reset hit a transfer in flight
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (mst_lost)) hits_COVP_030 <= hits_COVP_030 + 1;
// COVP-031: Requester domain active while slave domain in reset
always_ff @(posedge i_clk_mst) if (!(!i_rst_n_mst) && (!i_rst_n_slv)) hits_COVP_031 <= hits_COVP_031 + 1;
// COVP-032: Completer-side write Setup
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (o_apb_psel && !o_apb_penable && o_apb_pwrite)) hits_COVP_032 <= hits_COVP_032 + 1;
// COVP-033: Completer-side read Setup
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (o_apb_psel && !o_apb_penable && !o_apb_pwrite)) hits_COVP_033 <= hits_COVP_033 + 1;
// COVP-034: Completer ready in first Access cycle
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (o_apb_psel && o_apb_penable && i_apb_pready && slv_wcnt == 0)) hits_COVP_034 <= hits_COVP_034 + 1;
// COVP-035: Completer wait of 4 or more cycles
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (o_apb_psel && o_apb_penable && i_apb_pready && slv_wcnt >= 4)) hits_COVP_035 <= hits_COVP_035 + 1;
// COVP-036: Completer wait of 32 or more cycles
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (o_apb_psel && o_apb_penable && i_apb_pready && slv_wcnt >= 32)) hits_COVP_036 <= hits_COVP_036 + 1;
// COVP-037: Completer error response at end of Access
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (o_apb_psel && o_apb_penable && i_apb_pready && i_apb_pslverr)) hits_COVP_037 <= hits_COVP_037 + 1;
// COVP-038: Completer PREADY during Setup cycle
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (o_apb_psel && !o_apb_penable && i_apb_pready)) hits_COVP_038 <= hits_COVP_038 + 1;
// COVP-039: Completer-domain reset hit a transfer in flight
always_ff @(posedge i_clk_slv) if (!(!i_rst_n_slv) && (slv_lost)) hits_COVP_039 <= hits_COVP_039 + 1;
